INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10501, '2 Chronicles 4:3', '2 Chronicles', 4, 3, '&nbsp;د ډيګۍ ګېرچاپېره په ټوله بهرنۍ څنډه باندې د يو بل دپاسه د ښائسته ښکارېدو دوه قطارونه وُو. د ښائسته ښکارېدو دا قطارونه د غوَيانو د بُتانو په شکل کښې وُو، چې دا ټول د پوره ډيګۍ سره يوه ټُکړه شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10502, '2 Chronicles 4:4', '2 Chronicles', 4, 4, '&nbsp;ډيګۍ د زېړو د دولسو غوَيو په شا باندې پرته وه چې د غوَيو مخونه بهر وُو، چې په څلورو واړو طرفونو باندې درې درې غوَيو مخونه اړولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10503, '2 Chronicles 4:5', '2 Chronicles', 4, 5, '&nbsp;د ډيګۍ طرفونه درې اِنچۍ غټ وُو. د دې څنډه د پيالۍ د څنډې په شان وه، چې د نيلوفر د ګل په شان ښکارېده. په ډيګۍ کښې تقريباً شپېتۀ زره ليټره اوبۀ راتلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10504, '2 Chronicles 4:6', '2 Chronicles', 4, 6, '&nbsp;هغوئ لس ښانکونه هم جوړ کړل، چې پينځۀ د خُدائ پاک د کور په جنوبى طرف باندې او پينځۀ په شمالى طرف باندې کېښودلے شول. دا د ځناورو د برخو په کنګالولو کښې استعمالېدل کوم چې د نذرانې په توګه سوزولے کېدل. په غټه ډيګۍ کښې اوبو د اِمامانو دپاره وې چې د وينځلو دپاره يې استعمالولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10505, '2 Chronicles 4:9', '2 Chronicles', 4, 9, '&nbsp;هغوئ د اِمامانو دپاره يو دربار هم جوړ کړو او يو بهرنے لوئ دربار يې هم جوړ کړو. هغوئ دربار ته د ننوتلو دپاره دروازې هم جوړې کړې او دا دروازې يې په زېړو باندې پټې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10506, '2 Chronicles 4:10', '2 Chronicles', 4, 10, '&nbsp;ډيګۍ د خُدائ پاک د کور د نمرخاتۀ جنوبى طرف ګوټ سره نزدې اېښودے شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10507, '2 Chronicles 4:17', '2 Chronicles', 4, 17, '&nbsp;بادشاه دا هر څۀ د اُردن په مېدان کښې د سُکات او صريده په مينځ کښې په بټۍ کښې جوړ کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10508, '2 Chronicles 4:18', '2 Chronicles', 4, 18, '&nbsp;دومره زيات سامان په کښې جوړ شوے وو چې هيچا هم د هغه زېړو ټول وزن معلوم نۀ کړو چې په دې کښې استعمال شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10509, '2 Chronicles 4:19', '2 Chronicles', 4, 19, '&nbsp;سليمان بادشاه د خُدائ پاک د کور دپاره د سرو زرو دا سامان هم جوړ کړے وو، قربان‌ګاه او خُدائ پاک ته د پېش کړے شوې روټۍ مېز،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10510, '2 Chronicles 4:20', '2 Chronicles', 4, 20, '&nbsp;ډيوټ او د ښو سرو زرو ډيوې چې د منصوبې په مطابق د زيات مقدس ځائ ته مخامخ بلېدې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10511, '2 Chronicles 4:21', '2 Chronicles', 4, 21, '&nbsp;د ګلونو ښائسته والے، ډيوې او چمټې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10512, '2 Chronicles 4:22', '2 Chronicles', 4, 22, '&nbsp;د ډيوو سرپوښونه، جامونه، د خوشبويۍ لوښى او د بلو سکارو وړلو دپاره استعمالېدونکى لوښى. دا ټول څيزونه د سوچه سرو زرو نه جوړ شوى وُو. د خُدائ پاک د کور بهرنۍ دروازې او د زيات مقدس ځائ دروازې په سرو زرو باندې پټې کړے شوې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10513, '2 Chronicles 5:1', '2 Chronicles', 5, 1, '&nbsp;کله چې سليمان بادشاه د مالِک خُدائ د کور ټول کار ختم کړو، نو هغۀ د خُدائ پاک د کور په خزانو کښې هغه ټول څيزونه کېښودل کوم چې د هغۀ پلار داؤد مالِک خُدائ ته وقف کړى وُو يعنې سپين زر، سرۀ زر او نور سامان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10514, '2 Chronicles 5:2', '2 Chronicles', 5, 2, '&nbsp;بيا سليمان بادشاه د قبيلو او د بنى اِسرائيلو د ډلو ټول مشران راوغوښتل چې په يروشلم کښې راغونډ شى، او د مالِک خُدائ د لوظ صندوق د داؤد د ښار صيون نه يوسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10515, '2 Chronicles 5:3', '2 Chronicles', 5, 3, '&nbsp;نو هغوئ ټول د جونګړو د اختر په وخت کښې راغونډ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10516, '2 Chronicles 5:4', '2 Chronicles', 5, 4, '&nbsp;کله چې ټول مشران راغونډ شول، نو بيا ليويانو د لوظ صندوق اوچت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10517, '2 Chronicles 5:5', '2 Chronicles', 5, 5, '&nbsp;هغوئ دا د خُدائ پاک کور ته راوړو. اِمامانو او ليويانو هم د مالِک خُدائ د حضور خېمه او د دې ټول سامان د خُدائ پاک کور ته يوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10518, '2 Chronicles 5:6', '2 Chronicles', 5, 6, '&nbsp;سليمان بادشاه او ټول بنى اِسرائيليان د لوظ صندوق په مخکښې راغونډ شول او دومره ډېر ګډان او څاروى يې حلال کړل چې هغه د شمېر نه بهر وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10519, '2 Chronicles 5:7', '2 Chronicles', 5, 7, '&nbsp;بيا اِمامانو د مالِک خُدائ د لوظ صندوق د خپل خاص ځائ يعنې د خُدائ پاک د کور دنننى زيات مقدس ځائ ته راوړو او د وزرو والا مخلوق لاندې يې کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10520, '2 Chronicles 5:8', '2 Chronicles', 5, 8, '&nbsp;د هغوئ خورو ورو وزرو د لوظ صندوق او د وړولو بازوګان پټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10521, '2 Chronicles 5:9', '2 Chronicles', 5, 9, '&nbsp;کۀ څوک د زيات مقدس ځائ په مخکښې ولاړ وو نو هغوئ دا بازوګان ليدلے شول ځکه چې دا اوږدۀ وو، خو د بل يو ځائ نه هم نۀ ښکارېدل. هغه بازوګان تر ننه پورې هلته دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10522, '2 Chronicles 5:10', '2 Chronicles', 5, 10, '&nbsp;د لوظ صندوق دننه د کاڼو د هغه دوو تختو نه بغېر هيڅ هم نۀ وُو کومې چې موسىٰ د سينا د غرۀ سره په کښې اېښې وې، دا په هغه وخت کښې شوى وُو چې کله بنى اِسرائيليان د مِصر نه راروان وُو او مالِک خُدائ د هغوئ سره يو لوظ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10523, '2 Chronicles 5:14', '2 Chronicles', 5, 14, '&nbsp;نو اِمامانو د وريځې په وجه خِدمت نۀ شو تر سره کولے، ځکه چې د مالِک خُدائ جلال د خُدائ پاک کور ډک کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10524, '2 Chronicles 6:1', '2 Chronicles', 6, 1, '&nbsp;بيا سليمان دُعا وکړه، ”مالِکه خُدايه، تا په تکه توره وريځ کښې اوسېدل خوښ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10525, '2 Chronicles 6:2', '2 Chronicles', 6, 2, '&nbsp;اوس ما ستا دپاره يو عظيم کور جوړ کړے دے، يو داسې ځائ چې د همېشه دپاره به په کښې اوسېږې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10526, '2 Chronicles 6:3', '2 Chronicles', 6, 3, '&nbsp;ټول بنى اِسرائيليان هلته ولاړ وُو. بادشاه هغوئ ته مخ ورواړولو او د هغوئ دپاره يې د خُدائ پاک نه برکت وغوښتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10527, '2 Chronicles 6:4', '2 Chronicles', 6, 4, '&nbsp;هغۀ وفرمائيل، ”د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک ثناء صِفت دې وى. هغۀ چې زما د پلار داؤد سره کومه وعده کړې وه نو هغه يې پوره کړې ده کله چې هغۀ وفرمائيل چې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10528, '2 Chronicles 6:5', '2 Chronicles', 6, 5, '&nbsp;د هغه وخت نه چې د کله نه مې خپل خلق د مِصر نه راويستى دى تر اوسه پورې ما د بنى اِسرائيلو په مُلک کښې يو ښار هم نۀ دے خوښ کړے چې هلته زما د عبادت دپاره يو کور جوړ کړے شى او ما هيڅ څوک هم نۀ دے خوښ کړے چې زما د خلقو بنى اِسرائيلو مشرى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10529, '2 Chronicles 6:6', '2 Chronicles', 6, 6, '&nbsp;خو اوس ما يروشلم خوښ کړے دے چې دا به هغه ځائ وى چرته چې به زما عبادت کيږى او ما داؤد خوښ کړے دے چې زما په خلقو يعنې بنى اِسرائيلو باندې حکومت کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10530, '2 Chronicles 6:7', '2 Chronicles', 6, 7, '&nbsp;او سليمان خپله خبره جارى وساتله، ”زما د پلار داؤد منصوبه دا وه چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د عبادت دپاره يو کور جوړ کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10531, '2 Chronicles 6:8', '2 Chronicles', 6, 8, '&nbsp;خو مالِک خُدائ هغۀ ته وفرمائيل چې زما د نوم د درناوى دپاره د يو کور جوړولو په غوښتلو کښې تۀ په حقه يې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10532, '2 Chronicles 6:9', '2 Chronicles', 6, 9, '&nbsp;خو تۀ به هغه هيڅکله جوړ نۀ کړې بلکې هغه به ستا خپل زوئ وى چې زما دپاره کور جوړ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10533, '2 Chronicles 6:10', '2 Chronicles', 6, 10, '&nbsp;اوس مالِک خُدائ خپله وعده پوره کړې ده، زۀ د خپل پلار نه پس د بنى اِسرائيلو بادشاه جوړ شوے يم او ما د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د نوم درناوى دپاره يو کور جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10534, '2 Chronicles 6:11', '2 Chronicles', 6, 11, '&nbsp;ما په هغه کور کښې د لوظ صندوق اېښے دے چې په هغې کښې د هغه لوظ د کاڼو تختې دى کوم چې مالِک خُدائ د بنى اِسرائيلو سره کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10535, '2 Chronicles 6:12', '2 Chronicles', 6, 12, '&nbsp;بيا سليمان د خلقو په مخکښې لاړو او د قربان‌ګاه په مخکښې وړاندې ودرېدو او د دُعا دپاره يې لاسونه اوچت کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10536, '2 Chronicles 6:13', '2 Chronicles', 6, 13, '&nbsp;سليمان د زېړو يو ممبر هم جوړ کړے وو او دا يې د دربار په مينځ کښې اېښے وو. دا اووۀ نيم فټه اوږد اووۀ نيم فټه پلن او څلور نيم فټه اوچت وو. هغه په دې ممبر ودرېدلو، او بيا ټيټ شو، د هلته نه هر چا هغه وليدو. بيا هلته نه هغۀ آسمان طرف ته خپل لاسونه اوچت کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10537, '2 Chronicles 6:14', '2 Chronicles', 6, 14, '&nbsp;هغۀ سوال وکړو، ”اے مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه. په ټول آسمان او زمکه کښې ستا په شان خُدائ نشته. کله چې ستا خلق د زړۀ د اخلاصه ستا فرمانبردارى کوى نو تۀ هغوئ سره خپل لوظ پوره کوې او هغوئ ته خپله مينه ښائې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10538, '2 Chronicles 6:15', '2 Chronicles', 6, 15, '&nbsp;تا چې د خپل خِدمت کوونکى زما د پلار داؤد سره کومه وعده کړې ده نو هغه دې ټوله نن په خپله پوره کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10539, '2 Chronicles 6:16', '2 Chronicles', 6, 16, '&nbsp;نو اوس مالِکه خُدايه د بنى اِسرائيلو خُدايه پاکه، هم هغه وعده هم پوره کړه چې کومه تا زما پلار سره کړې ده چې هغۀ ته دې فرمائيلى وُو چې د هغۀ د اولاد نه به همېشه داسې يو کس وى چې په بنى اِسرائيلو به بادشاهى کوى، کۀ هغوئ د هغۀ په شان ستا په قانون باندې په توجو سره عمل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10540, '2 Chronicles 6:17', '2 Chronicles', 6, 17, '&nbsp;نو اوس مالِکه خُدايه د بنى اِسرائيلو خُدايه پاکه، هغه هر څۀ پوره کړه چې تا د خپل خِدمت کوونکى داؤد سره وعده کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10541, '2 Chronicles 6:18', '2 Chronicles', 6, 18, '&nbsp;خو اے خُدايه پاکه، ولې تۀ به په رښتيا د بنيادمو سره اوسېږې؟ ستا هستى خو دومره لويه ده چې آسمانونه، لوئ آسمانونه هم ستا دپاره واړۀ دى نو بيا دا کور خو ډېر زيات وړوکے دے چې ما جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10542, '2 Chronicles 6:19', '2 Chronicles', 6, 19, '&nbsp;مالِکه خُدايه زما خُدايه پاکه، زۀ ستا خِدمت کوونکے يم. زما سوال واوره او چې ما کوم سوال درته کړے دے هغه پوره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10543, '2 Chronicles 6:20', '2 Chronicles', 6, 20, '&nbsp;تۀ په دې کور او په دې ځائ باندې شپه او ورځ نظر ساته چې تا فرمائيلى دى چې تۀ به دلته خپل نوم ږدې. زۀ چې دې ځائ ته مخامخ کومه او دُعا کوم نو هغه همېشه اوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10544, '2 Chronicles 6:21', '2 Chronicles', 6, 21, '&nbsp;د خپل خِدمت کوونکى دُعاګانې او د خپلو خلقو بنى اِسرائيلو دُعاګانې اوره چې کله هغوئ دې ځائ ته مخ کوى او دُعا کوى. تۀ په آسمان کښې اوره چرته چې تۀ اوسېږې او چې کله تۀ اورې نو معافى کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10545, '2 Chronicles 6:22', '2 Chronicles', 6, 22, '&nbsp;کله چې په يو کس اِلزام ولګوى چې بل چا ورسره بد کړى دى او په دې کور کښې ستا قربان‌ګاه ته راوستلے شى چې هغه قسم وکړى چې بې‌ګناه دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10546, '2 Chronicles 6:23', '2 Chronicles', 6, 23, '&nbsp;نو اے مالِکه خُدايه، په آسمان کښې اوره او د خپلو خِدمت کوونکو عدالت کوه. مجرم له هغه شان سزا ورکوه چې څنګه يې حقدار وى او چې څوک بې‌ګناه وى نو هغه پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10547, '2 Chronicles 6:24', '2 Chronicles', 6, 24, '&nbsp;کله چې ستا خلق بنى اِسرائيليان د خپلو دشمنانو نه شکست وخورى ځکه چې هغوئ به ستا خِلاف ګناه کړې وى او چې بيا هغوئ تا ته راوګرځى او دې کور ته راشى او تا ته په عاجزۍ سره د معافۍ دپاره سوال وکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10548, '2 Chronicles 6:25', '2 Chronicles', 6, 25, '&nbsp;نو په آسمان کښې د هغوئ سوال اوره. د خپلو خلقو سزا معاف کوه او واپس يې هغه مُلک ته راوله چې کوم تا هغوئ او د هغوئ پلار نيکۀ له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10549, '2 Chronicles 6:26', '2 Chronicles', 6, 26, '&nbsp;کله چې په دې وجه د آسمان نه باران ايسار شى چې ستا خلقو ګناه کړې وى او کله چې هغوئ په عاجزۍ سره دې کور ته مخ کړى او توبه وباسى', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10550, '2 Chronicles 6:27', '2 Chronicles', 6, 27, '&nbsp;نو په آسمان کښې د هغوئ سوال اوره او د خپلو خِدمت کوونکو د بنى اِسرائيلو ګناهونه معاف کوه او هغه څۀ ورته ښايه چې کوم صحيح وى. بيا اے مالِکه خُدايه، په دې خپل مُلک باندې باران راولېږه، کوم چې تا خپلو خلقو له ورکړے دے چې د همېشه دپاره د هغوئ ميراث وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10551, '2 Chronicles 6:28', '2 Chronicles', 6, 28, '&nbsp;کله چې په هغه مُلک کښې قحط، وبا وى يا د ګرمې هوا يا د قحطۍ د مُولخانو په وجه فصلونه تباه کيږى، يا چې دشمنان ستا د خلقو ښار محاصره کړى، يا چې کله د هغوئ په مينځ کښې يو مرض يا بيمارى وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10552, '2 Chronicles 6:29', '2 Chronicles', 6, 29, '&nbsp;نو د هغوئ دُعاګانې اوره. کۀ ستا د خلقو بنى اِسرائيلو نه هر څوک هم، د مصيبت او تکليف په وخت کښې خپل لاسونه د دُعا دپاره دې کور ته اوچت کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10553, '2 Chronicles 6:30', '2 Chronicles', 6, 30, '&nbsp;نو د هغوئ سوال اوره. په آسمان کښې په خپل کور کښې د هغوئ سوال اوره او هغوئ معاف کوه. صِرف تۀ د بنى آدم د زړۀ په منصوبو پوهېږې. هر چا سره هغه شان سلوک کوه چې څنګه يې حقدار وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10554, '2 Chronicles 6:31', '2 Chronicles', 6, 31, '&nbsp;نو چې داسې ستا خلق ستا نه يريږى او چې هغوئ همېشه ستا تابعدارى کوى چې کله په هغه مُلک کښې اوسيږى چې تا زمونږ پلار نيکۀ له ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10555, '2 Chronicles 6:32', '2 Chronicles', 6, 32, '&nbsp;د پردى مُلک هغه خلق چې په لرې مُلک کښې اوسيږى چې هغوئ دا واورى چې تۀ څومره لوئ او طاقتور يې او د کار کولو دپاره تۀ همېشه څومره تيار يې او چې کله هغوئ د دُعا دپاره دې کور ته راشى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10556, '2 Chronicles 6:33', '2 Chronicles', 6, 33, '&nbsp;نو تۀ د هغوئ سوال اوره. چرته چې تۀ اوسېږې، د هغوئ سوال اوره او هغه څۀ کوه چې دوئ يې غواړى، نو چې داسې د ټولې دُنيا خلق دې وپېژنى او ستا د خلقو بنى اِسرائيلو په شان ستا نه ويريږى. بيا به هغوئ ته پته ولګى چې ما دا کوم کور جوړ کړے دے په دې پورې ستا نوم تړلے شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10557, '2 Chronicles 6:34', '2 Chronicles', 6, 34, '&nbsp;کله چې تۀ خپلو خلقو له حُکم ورکړې چې د خپلو دشمنانو خِلاف جنګ له لاړ شئ او هغوئ تا ته سوال وکړى، چې هغوئ چرته هم وى او مخ يې دې ښار ته وى کوم چې تا خوښ کړے دے او دې کور ته يې مخ وى کوم چې ما ستا دپاره جوړ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10558, '2 Chronicles 6:35', '2 Chronicles', 6, 35, '&nbsp;نو د هغوئ سوال اوره. په آسمان کښې د هغوئ سوال اوره او هغوئ له فتح ورکوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10559, '2 Chronicles 6:36', '2 Chronicles', 6, 36, '&nbsp;کله چې ستا خلق ستا خِلاف ګناه وکړى او داسې هيڅ څوک نشته چې ګناه نۀ کوى او په غصه کښې تۀ د هغوئ دشمنان پرېږدې چې هغوئ له شکست ورکړى او هغوئ يو بل مُلک ته قېديان بوځى، کۀ هغه مُلک لرې هم وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10560, '2 Chronicles 6:37', '2 Chronicles', 6, 37, '&nbsp;نو د خپلو خلقو سوال اوره. کۀ هلته په هغه مُلک کښې هغوئ توبه وباسى او تا ته سوال وکړى او دا اِقرار وکړى، چې مونږ ډېر ګناهګار او بدعمله يو، نو اے مالِکه خُدايه، د هغوئ سوال اوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10561, '2 Chronicles 6:38', '2 Chronicles', 6, 38, '&nbsp;کۀ په هغه مُلک کښې هغوئ په رښتيا او د زړۀ د اخلاصه توبه وباسى او سوال وکړى چې مخ يې دې مُلک ته وى کوم چې تا د هغوئ پلار نيکۀ له ورکړے دے، هغه ښار چې کوم تا خوښ کړے دے او هغه کور چې ما ستا دپاره جوړ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10562, '2 Chronicles 6:39', '2 Chronicles', 6, 39, '&nbsp;نو د هغوئ سوال اوره. په آسمان کښې، چرته چې اوسېږې په هغوئ مهربان شه او د خپلو خلقو ټول ګناهونه معاف کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10563, '2 Chronicles 6:40', '2 Chronicles', 6, 40, '&nbsp;نو اے زما خُدايه پاکه، مونږ ته وګوره او هغه دُعاګانې قبولې کړه چې په دې ځائ کښې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10564, '2 Chronicles 6:41', '2 Chronicles', 6, 41, '&nbsp;مالِکه خُدايه اے خُدايه پاکه، د خپل لوظ صندوق سره دې خاص ځائ ته دننه لاړ شه چې دا صندوق ستا د طاقت نښه ده. اے مالِکه خُدايه پاکه، ستا اِمامانو ته دې خلاصون مِلاو شى او ستا ايماندار خِدمت کوونکى دې ستا د مهربانۍ په وجه خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10565, '2 Chronicles 6:42', '2 Chronicles', 6, 42, '&nbsp;مالِکه خُدايه اے خُدايه پاکه، کوم بادشاه چې تا خوښ کړے دے هغه مۀ رد کوه. هغه مينه ياده کړه چې کومه تا د خپل خِدمت کوونکى داؤد سره کړې ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10566, '2 Chronicles 7:1', '2 Chronicles', 7, 1, '&nbsp;کله چې سليمان بادشاه خپله دُعا ختمه کړه نو د آسمان نه اور راکوز شو او کومې نذرانې چې پېش کړے شوې وې هغه يې وسوزولې او د خُدائ پاک کور د مالِک خُدائ د حضور د جلال نه ډک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10567, '2 Chronicles 7:2', '2 Chronicles', 7, 2, '&nbsp;اِمامان د مالِک خُدائ کور ته ځکه نۀ شول ننوتلے چې د مالِک خُدائ کور د جلال نه ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10568, '2 Chronicles 7:3', '2 Chronicles', 7, 3, '&nbsp;کله چې ټولو بنى اِسرائيلو وليدل چې اور راکوزېدلو او د مالِک خُدائ د جلال نه ډک حضور هغه کور ډک کړے وو، نو هغوئ پړمخې په زمکه وغورزېدل، سجده يې وکړه او د مالِک خُدائ په ثناء صِفت کښې يې وفرمائيل، ”هغه مهربان دے، د هغۀ د وفا نه ډکه مينه د همېشه دپاره ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10569, '2 Chronicles 7:4', '2 Chronicles', 7, 4, '&nbsp;بيا سليمان او ټولو خلقو مالِک خُدائ ته نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10570, '2 Chronicles 7:5', '2 Chronicles', 7, 5, '&nbsp;هغۀ دوويشت زره څاروى او يو سل او شل زره ګډان د سلامتۍ نذرانې په توګه حلال کړل. نو داسې هغۀ او ټولو خلقو د خُدائ پاک کور وقف کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10571, '2 Chronicles 7:6', '2 Chronicles', 7, 6, '&nbsp;اِمامان په هغه مقررو شوو ځايونو باندې ولاړ وُو او ليويان ورسره وُو، هغوئ وفرمائيل، ”د هغۀ نۀ ختمېدونکې مينه د همېشه دپاره ده.“ هغوئ د موسيقۍ د هغه سامان سره په يو انداز سندرې وئيلې کوم چې داؤد بادشاه د مالِک خُدائ د ثناء صِفت دپاره جوړ کړى وُو. ليويانو ته مخامخ اِمامانو بيګلې غږولې او په دې دوران کښې ټول بنى اِسرائيليان ولاړ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10572, '2 Chronicles 7:7', '2 Chronicles', 7, 7, '&nbsp;سليمان د دربار مرکزى حِصه وقف کړه، کوم ځائ چې د مالِک خُدائ د کور په مخکښې وو او بيا يې هلته پوره سوزېدونکې نذرانې، د غلې نذرانې او د سلامتۍ د نذرانې وازګه يې پېش کړه، هغۀ داسې ځکه وکړل چې هغۀ د زېړو کومه قربان‌ګاه جوړه کړې وه نو هغه قربان‌ګاه د دې ټولو نذرانو دپاره ډېره وړه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10573, '2 Chronicles 7:8', '2 Chronicles', 7, 8, '&nbsp;سليمان او ټولو بنى اِسرائيلو اووۀ ورځې د جونګړو اختر وکړو. هلته په شمال کښې د حمات دَرې نه واخله په جنوب کښې د مِصر د سرحد پورې يوه لويه ګڼه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10574, '2 Chronicles 7:9', '2 Chronicles', 7, 9, '&nbsp;هغوئ اووۀ ورځې د قربان‌ګاه د وقف کولو دپاره او اووۀ نورې ورځې د اختر دپاره تېرې کړې. په آخرى ورځ هغوئ يو آخرى تقريب وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10575, '2 Chronicles 7:10', '2 Chronicles', 7, 10, '&nbsp;په ورپسې ورځ يعنې د اوومې مياشتې په درويشتمه ورځ، سليمان خلق کورونو ته ولېږل. هغوئ په هغه ټولو برکتونو باندې خوشحاله وُو کوم چې مالِک خُدائ بنى اِسرائيلو له، داؤد او سليمان له ورکړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10576, '2 Chronicles 7:11', '2 Chronicles', 7, 11, '&nbsp;کله چې سليمان بادشاه د مالِک خُدائ کور او محل او د دې دپاره ټولې منصوبې مکملې کړې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10577, '2 Chronicles 7:12', '2 Chronicles', 7, 12, '&nbsp;نو مالِک خُدائ هغۀ ته د شپې راڅرګند شو او هغۀ ته يې وفرمائيل، ”ما ستا دُعا اورېدلې ده او دا ځائ د يو داسې ځائ په توګه قبلوم چرته به چې ما ته نذرانې پېش کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10578, '2 Chronicles 7:13', '2 Chronicles', 7, 13, '&nbsp;کله هم چې زۀ باران نۀ وروم يا د قحطۍ مُلخان راولېږم چې فصلونه وخورى او يا په خپلو خلقو باندې يوه وبا راولېږم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10579, '2 Chronicles 7:14', '2 Chronicles', 7, 14, '&nbsp;نو کۀ زما خلق څوک چې زما خپل خلق دى ما ته سوال وکړى او توبه وباسى او چې هغوئ کوم بد عمل کوى د هغې نه راوګرځى، نو بيا به زۀ په آسمان کښې د هغوئ سوال واورم، د هغوئ ګناهونه به معاف کړم او د هغوئ زمکه به بيا آباده کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10580, '2 Chronicles 7:15', '2 Chronicles', 7, 15, '&nbsp;زۀ به په دې کور باندې نظر وساتم او چې په دې کور کښې کومې دُعاګانې وشى نو د هغې اورېدو دپاره به تيار يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10581, '2 Chronicles 7:16', '2 Chronicles', 7, 16, '&nbsp;ځکه چې دا ما خوښ کړے دے او دا مې د دې دپاره پاک ګرځولے دے چې دلته به د تل دپاره زما عبادت کيږى. زۀ به په دې باندې نظر ساتم او تل به يې حِفاظت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10582, '2 Chronicles 7:17', '2 Chronicles', 7, 17, '&nbsp;کۀ تۀ د خپل پلار داؤد په شان په وفادارۍ سره زما خِدمت کوې، زما قانون منې او هغه هر څۀ کوې چې ما يې حُکم کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10583, '2 Chronicles 7:18', '2 Chronicles', 7, 18, '&nbsp;نو زۀ به هغه وعده پوره کړم کومه چې ما ستا پلار داؤد سره کړې وه کله چې ما هغۀ ته وفرمائيل چې په بنى اِسرائيلو کښې به ستا اولاد همېشه حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10584, '2 Chronicles 7:19', '2 Chronicles', 7, 19, '&nbsp;خو کۀ تۀ او ستا خلق کله هم هغه قانون او حُکمونه نۀ منئ چې ما تاسو له درکړى دى او د نورو معبودانو عبادت وکړئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10585, '2 Chronicles 7:20', '2 Chronicles', 7, 20, '&nbsp;نو بيا به زۀ تاسو د هغه مُلک نه لرې کړم چې ما درکړے دے او زۀ به دا کور پرېږدم چې ما دا ځائ د دې دپاره مخصوص کړے دے چرته به چې زما عبادت کيږى. نو ټول قومونه به په دې پورې خندا کوى او سپکاوے به يې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10586, '2 Chronicles 7:21', '2 Chronicles', 7, 21, '&nbsp;دا کور اوس د شان او شوکت والا دے خو چې بيا کله هم څوک په دې تېريږى نو حېران به شى او تپوس به کوى چې، مالِک خُدائ د دې مُلک او د دې کور سره داسې بد ولې کړى دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10587, '2 Chronicles 7:22', '2 Chronicles', 7, 22, '&nbsp;نو خلق به په جواب کښې وائى چې، دا ځکه وشول چې هغوئ مالِک خُدائ خپل خُدائ پاک پرېښودو، چا چې د هغوئ پلار نيکۀ د مِصر نه راوويستل. هغوئ نورو معبودانو ته ورواوړېدل او د هغوئ عبادت يې وکړو. نو ځکه مالِک خُدائ په هغوئ باندې دا مصيبت راوستلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10588, '2 Chronicles 8:1', '2 Chronicles', 8, 1, '&nbsp;سليمان په خپل محل او د مالِک خُدائ په کور جوړولو کښې شل کاله ولګول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10589, '2 Chronicles 8:2', '2 Chronicles', 8, 2, '&nbsp;هغۀ هغه ښارونه هم بيا جوړ کړل چې حيرام بادشاه ورکړى وُو او بنى اِسرائيليان يې ورولېږل چې په هغې کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10590, '2 Chronicles 8:3', '2 Chronicles', 8, 3, '&nbsp;سليمان بيا حمات ضوباه ته لاړو او دا علاقه يې قبضه کړه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10591, '2 Chronicles 8:4', '2 Chronicles', 8, 4, '&nbsp;او په صحرا کښې د پَخو دېوالونو ښار تدمور يې بيا جوړ کړو. هغۀ په حمات کښې هغه ټول ښارونه هم بيا جوړ کړل چې کوم ښارونه د ګودامونو دپاره استعمالېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10592, '2 Chronicles 8:5', '2 Chronicles', 8, 5, '&nbsp;سليمان دا ښارونه هم بيا جوړ کړل، پاسنے بيت‌حورون او لاندينے بيت‌حورون چې دا د پَخو دېوالونو ښارونه وُو چې مضبوطې دروازې يې لرلې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10593, '2 Chronicles 8:6', '2 Chronicles', 8, 6, '&nbsp;د بعلات ښار، هغه ټول ښارونه چې د سامان ګودامونه وُو او هغه ښارونه چرته چې د هغۀ آسونه او جنګى ګاډۍ ودرېدلې. هغۀ د يروشلم، لبنان او د هغه ټولې علاقې چې د هغۀ په بادشاهۍ کښې وې، نو چې کوم آبادول غوښتل هغه يې سر ته ورسول او بادشاهى يې کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10594, '2 Chronicles 8:9', '2 Chronicles', 8, 9, '&nbsp;د بنى اِسرائيلو نه په زور کار نۀ شو اخستلے، خو د فوجيانو، آفسرانو، د جنګى ګاډو مشرانو او په آسونو سوارو کسانو په توګه يې خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10595, '2 Chronicles 8:10', '2 Chronicles', 8, 10, '&nbsp;سليمان د بنى اِسرائيلو نه دوه نيم سوه آفسران مقرر کړل چې په دغه خلقو مشرى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10596, '2 Chronicles 8:11', '2 Chronicles', 8, 11, '&nbsp;سليمان خپله ښځه يعنې د مِصر د فِرعون لور د داؤد د ښار نه هغه کور ته بوتله چې کوم يې د هغې دپاره جوړ کړے وو. هغۀ وفرمائيل، ”هغه دې د بنى اِسرائيلو بادشاه داؤد په محل کښې نۀ اوسيږى، ځکه چې چرته د لوظ صندوق پاتې شوے وو نو هغه ځائ مقدس دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10597, '2 Chronicles 8:12', '2 Chronicles', 8, 12, '&nbsp;سليمان په هغه قربان‌ګاه باندې مالِک خُدائ ته سوزېدونکې نذرانې پېش کړې کومه چې هغۀ د خُدائ پاک د کور په مخکښې جوړه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10598, '2 Chronicles 8:13', '2 Chronicles', 8, 13, '&nbsp;هغۀ د هرې مقدسې ورځې دپاره د موسىٰ د شريعت د حُکم په مطابق سوزېدونکې نذرانې پېش کړې، د سبت د ورځو، د نوې مياشتې اخترونو او د کال درې کلنى اخترونو: د پتيرې روټۍ اختر، د رېبلو اختر او د جونګړو اختر.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10599, '2 Chronicles 8:14', '2 Chronicles', 8, 14, '&nbsp;اِمامانو ته د ذمه وارو حواله کولو دپاره سليمان د خپل پلار داؤد په اصُولو باندې عمل وکړو. هغۀ ليويان هم مقرر کړل چې په ثناء صِفت کولو کښې او د اِمامانو سره د هغوئ په کارونو کښې مدد کوى. او هغۀ د ډلو په مطابق په دروازو باندې څوکيداران هم ودرول، ځکه چې د خُدائ پاک خِدمت کوونکى داؤد هم دغه شان حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10600, '2 Chronicles 8:15', '2 Chronicles', 8, 15, '&nbsp;داؤد چې د خزانو او نورو معامِلو دپاره اِمامانو او ليويانو ته کوم اصُول ښودلى وُو هغه پوره پوره سر ته رسېدلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');